def percent_to_points(apps, schema_editor):
    """Thresholds were percentages; they become points of the exam's biggest variant (rounded up, so
    `score >= points` keeps meaning `percentage >= old threshold` for whole-point questions)."""
    Examination = apps.get_model("examinations", "Examination")
    VariantQuestion = apps.get_model("examinations", "VariantQuestion")
    for exam in Examination.objects.all():
        totals = {}
        for vid, pts in VariantQuestion.objects.filter(variant__examination=exam).values_list("variant_id", "question__points"):
            totals[vid] = totals.get(vid, 0) + float(pts)
        top = max(totals.values(), default=0)
        if not top:
            continue  # no questions yet: the admin sets the points when building it
        conv = lambda pct: Decimal(math.ceil(float(pct) * top / 100 - 1e-9))
        exam.passing_score = conv(exam.passing_score)
        if exam.high_threshold is not None:
            exam.high_threshold = conv(exam.high_threshold)
        exam.save(update_fields=["passing_score", "high_threshold"])


